// goldenDir is the directory with outputs generated by the original .NET CLI.
const goldenDir = "/tmp/opencode/golden"

func requireGolden(t *testing.T) string {
	t.Helper()
	info, err := os.Stat(goldenDir)
	if err != nil || !info.IsDir() {
		t.Skipf("golden directory %s not available", goldenDir)
	}
	return goldenDir
}

func runCommand(t *testing.T, module core.OpticalDiscModule, command string, args ...string) (core.DiscJobResult, error) {
	t.Helper()
	return module.Execute(context.Background(), core.DiscJobRequest{Command: command, Args: args}, nil)
}

// (a) bd-info with a nil loader.
func TestBdInfo(t *testing.T) {
	module := bluray.NewModule(nil)
	result, err := runCommand(t, module, "bd-info")
	if err != nil {
		t.Fatalf("bd-info failed: %v", err)
	}
	if result.ExitCode != 0 {
		t.Fatalf("exit code = %d, want 0", result.ExitCode)
	}
	if !strings.Contains(result.Summary, `"standard": "ISO/IEC 30190:2021"`) {
		t.Error("summary missing standard line")
	}
	if !strings.Contains(result.Summary, `"preset": "bd-r-sl-25gb"`) {
		t.Error("summary missing preset id")
	}
}

// (b) bd-encode: 65536 payload bytes → 76880 ECC bytes.
func TestBdEncode(t *testing.T) {
	dir := t.TempDir()
	input := filepath.Join(dir, "payload.bin")
	output := filepath.Join(dir, "ecc.bin")
	payload := make([]byte, 65536)
	for i := range payload {
		payload[i] = byte(i * 37)
	}
	if err := os.WriteFile(input, payload, 0o666); err != nil {
		t.Fatal(err)
	}
	module := bluray.NewModule(nil)
	result, err := runCommand(t, module, "bd-encode",
		"--input", input, "--output", output, "--psn", "0x100000")
	if err != nil {
		t.Fatalf("bd-encode failed: %v", err)
	}
	if result.ExitCode != 0 {
		t.Fatalf("exit code = %d, want 0", result.ExitCode)
	}
	info, err := os.Stat(output)
	if err != nil {
		t.Fatal(err)
	}
	if info.Size() != 76880 {
		t.Fatalf("output size = %d, want 76880", info.Size())
	}
	wantSummary := "BD ECC diagnostic: 76880 bytes; no 17PP/RUB or filesystem in this file."
	if result.Summary != wantSummary {
		t.Fatalf("summary = %q, want %q", result.Summary, wantSummary)
	}
}

// (c) bd-probe: 32 sectors of a constant scrambled byte.
func TestBdProbe(t *testing.T) {
	dir := t.TempDir()
	output := filepath.Join(dir, "probe.bin")
	module := bluray.NewModule(nil)
	result, err := runCommand(t, module, "bd-probe",
		"--output", output, "--start-sector", "0", "--sectors", "32", "--byte", "0x00")
	if err != nil {
		t.Fatalf("bd-probe failed: %v", err)
	}
	if result.ExitCode != 0 {
		t.Fatalf("exit code = %d, want 0", result.ExitCode)
	}
	info, err := os.Stat(output)
	if err != nil {
		t.Fatal(err)
	}
	if info.Size() != 32*2048 {
		t.Fatalf("output size = %d, want %d", info.Size(), 32*2048)
	}
}

// writeTestPNG creates a small deterministic grayscale-gradient PNG.
func writeTestPNG(t *testing.T, path string, size int) {
	t.Helper()
	img := image.NewGray(image.Rect(0, 0, size, size))
	for y := 0; y < size; y++ {
		for x := 0; x < size; x++ {
			img.SetGray(x, y, color.Gray{Y: byte((x + y) % 256)})
		}
	}
	file, err := os.Create(path)
	if err != nil {
		t.Fatal(err)
	}
	defer file.Close()
	if err := png.Encode(file, img); err != nil {
		t.Fatal(err)
	}
}

// (d) bd-generate with a tiny generated PNG.
func TestBdGenerate(t *testing.T) {
	dir := t.TempDir()
	input := filepath.Join(dir, "input.png")
	output := filepath.Join(dir, "bd.iso")
	writeTestPNG(t, input, 8)
	module := bluray.NewModule(bluray.LoadGray8)
	result, err := runCommand(t, module, "bd-generate",
		"--input", input, "--output", output, "--total-sectors", "1024")
	if err != nil {
		t.Fatalf("bd-generate failed: %v", err)
	}
	if result.ExitCode != 0 {
		t.Fatalf("exit code = %d, want 0 (summary %q)", result.ExitCode, result.Summary)
	}
	info, err := os.Stat(output)
	if err != nil {
		t.Fatal(err)
	}
	if info.Size() != 1024*2048 {
		t.Fatalf("ISO size = %d, want %d", info.Size(), 1024*2048)
	}
	// The C# module always writes the recovery sidecar next to the ISO.
	sidecar := output + ".json"
	sidecarInfo, err := os.Stat(sidecar)
	if err != nil {
		t.Fatalf("sidecar missing: %v", err)
	}
	if sidecarInfo.Size() == 0 {
		t.Fatal("sidecar is empty")
	}
	content, err := os.ReadFile(sidecar)
	if err != nil {
		t.Fatal(err)
	}
	if !strings.Contains(string(content), `"format": "bd-r-image-v1"`) {
		t.Error("sidecar missing format marker")
	}
	if !strings.HasSuffix(string(content), "}\n") {
		t.Error("sidecar must end with a newline")
	}
}

// --- Golden comparisons against the original .NET CLI outputs ---

func TestGoldenBdInfo(t *testing.T) {
	dir := requireGolden(t)
	golden, err := os.ReadFile(filepath.Join(dir, "bd-info.json"))
	if err != nil {
		t.Fatal(err)
	}
	module := bluray.NewModule(nil)
	result, err := runCommand(t, module, "bd-info")
	if err != nil {
		t.Fatalf("bd-info failed: %v", err)
	}
	if result.Summary != string(golden) {
		t.Fatalf("bd-info JSON mismatch:\n--- got ---\n%s\n--- want ---\n%s", result.Summary, golden)
	}
}

func TestGoldenBdEncode(t *testing.T) {
	dir := requireGolden(t)
	work := t.TempDir()
	input := filepath.Join(work, "bd-payload.bin")
	output := filepath.Join(work, "bd-ecc.bin")
	payload, err := os.ReadFile(filepath.Join(dir, "bd-payload.bin"))
	if err != nil {
		t.Fatal(err)
	}
	if err := os.WriteFile(input, payload, 0o666); err != nil {
		t.Fatal(err)
	}
	module := bluray.NewModule(nil)
	if _, err := runCommand(t, module, "bd-encode",
		"--input", input, "--output", output, "--psn", "0x100000"); err != nil {
		t.Fatalf("bd-encode failed: %v", err)
	}
	got, err := os.ReadFile(output)
	if err != nil {
		t.Fatal(err)
	}
	golden, err := os.ReadFile(filepath.Join(dir, "bd-ecc.bin"))
	if err != nil {
		t.Fatal(err)
	}
	if !bytes.Equal(got, golden) {
		t.Fatalf("bd-encode output differs from golden (%d vs %d bytes)", len(got), len(golden))
	}
}

func TestGoldenBdProbe(t *testing.T) {
	dir := requireGolden(t)
	output := filepath.Join(t.TempDir(), "bd-probe.bin")
	module := bluray.NewModule(nil)
	if _, err := runCommand(t, module, "bd-probe",
		"--output", output, "--start-sector", "0", "--sectors", "32", "--byte", "0x55"); err != nil {
		t.Fatalf("bd-probe failed: %v", err)
	}
	got, err := os.ReadFile(output)
	if err != nil {
		t.Fatal(err)
	}
	golden, err := os.ReadFile(filepath.Join(dir, "bd-probe.bin"))
	if err != nil {
		t.Fatal(err)
	}
	if !bytes.Equal(got, golden) {
		t.Fatal("bd-probe output differs from golden")
	}
}

// normalizeSidecar replaces run-specific paths and timestamps so the sidecar
// can be compared byte-for-byte.
func normalizeSidecar(content []byte, replacements [][2]string) string {
	text := string(content)
	for _, pair := range replacements {
		text = strings.ReplaceAll(text, pair[0], pair[1])
	}
	// Mask the timestamp values.
	timestamp := regexp.MustCompile(`"(generatedUtc|udfTimestamp)": "[^"]*"`)
	return timestamp.ReplaceAllString(text, `"$1": "<timestamp>"`)
}

// normalizeGoldenSidecar applies the timestamp mask to a golden sidecar whose
// paths already point at the golden directory.
func normalizeGoldenSidecar(content []byte) string {
	return normalizeSidecar(content, nil)
}

func TestGoldenBdIso(t *testing.T) {
	dir := requireGolden(t)
	work := t.TempDir()
	output := filepath.Join(work, "bd.iso")
	module := bluray.NewModule(bluray.LoadGray8)
	result, err := runCommand(t, module, "bd-generate",
		"--input", filepath.Join(dir, "input.png"),
		"--output", output,
		"--total-sectors", "1024")
	if err != nil {
		t.Fatalf("bd-generate failed: %v", err)
	}
	if result.ExitCode != 0 {
		t.Fatalf("exit code = %d, want 0 (summary %q)", result.ExitCode, result.Summary)
	}
	got, err := os.ReadFile(output)
	if err != nil {
		t.Fatal(err)
	}
	golden, err := os.ReadFile(filepath.Join(dir, "bd.iso"))
	if err != nil {
		t.Fatal(err)
	}
	if !bytes.Equal(got, golden) {
		firstDiff := -1
		for i := 0; i < len(got) && i < len(golden); i++ {
			if got[i] != golden[i] {
				firstDiff = i
				break
			}
		}
		t.Fatalf("bd.iso differs from golden (first diff at byte %d of %d)", firstDiff, len(golden))
	}

	gotSidecar, err := os.ReadFile(output + ".json")
	if err != nil {
		t.Fatal(err)
	}
	goldenSidecar, err := os.ReadFile(filepath.Join(dir, "bd.iso.json"))
	if err != nil {
		t.Fatal(err)
	}
	normalized := normalizeSidecar(gotSidecar, [][2]string{{work, dir}})
	if normalized != normalizeGoldenSidecar(goldenSidecar) {
		t.Fatalf("bd.iso.json mismatch:\n--- got ---\n%s\n--- want ---\n%s", normalized, goldenSidecar)
	}
}

func TestGoldenBdDataIso(t *testing.T) {
	dir := requireGolden(t)
	work := t.TempDir()
	output := filepath.Join(work, "bd-data.iso")
	module := bluray.NewModule(bluray.LoadGray8)
	result, err := runCommand(t, module, "bd-generate",
		"--input", filepath.Join(dir, "input.png"),
		"--output", output,
		"--total-sectors", "2048",
		"--data-dir", filepath.Join(dir, "data"),
		"--volume-label", "MYBD")
	if err != nil {
		t.Fatalf("bd-generate failed: %v", err)
	}
	if result.ExitCode != 0 {
		t.Fatalf("exit code = %d, want 0 (summary %q)", result.ExitCode, result.Summary)
	}
	got, err := os.ReadFile(output)
	if err != nil {
		t.Fatal(err)
	}
	golden, err := os.ReadFile(filepath.Join(dir, "bd-data.iso"))
	if err != nil {
		t.Fatal(err)
	}
	// The UDF volume embeds the plan-time recording timestamp (UtcNow): the
	// primary/reserve volume descriptors (volume set id + recording time), the
	// logical volume integrity descriptor and the file-set descriptor. Mask
	// those fields along with each descriptor's tag checksum (byte 4) and tag
	// CRC (bytes 8..9). File entries (tag 261) additionally differ from the
	// .NET golden in the uid/gid/permissions fields (offsets 36..47): the Go
	// writers default to root ownership and copy modes from the source.
	maskSectors := []struct {
		lba    int64
		ranges [][2]int
	}{
		{32, [][2]int{{4, 5}, {8, 10}, {72, 88}, {376, 388}}},   // main PVD
		{1792, [][2]int{{4, 5}, {8, 10}, {72, 88}, {376, 388}}}, // reserve PVD (volumeSectors-256)
		{48, [][2]int{{4, 5}, {8, 10}, {16, 28}}},               // integrity descriptor
		{288, [][2]int{{4, 5}, {8, 10}, {16, 28}}},              // file-set descriptor (first partition LBA)
	}
	mask := func(data []byte) {
		for _, sector := range maskSectors {
			base := sector.lba * 2048
			for _, r := range sector.ranges {
				for i := base + int64(r[0]); i < base+int64(r[1]); i++ {
					data[i] = 0
				}
			}
		}
		// File entries anywhere in the image (tag 261).
		for lba := int64(0); (lba+1)*2048 <= int64(len(data)); lba++ {
			base := lba * 2048
			if binary.LittleEndian.Uint16(data[base:]) != 261 {
				continue
			}
			data[base+4] = 0
			data[base+8] = 0
			data[base+9] = 0
			for i := int64(36); i < 48; i++ {
				data[base+i] = 0
			}
		}
	}
	mask(got)
	mask(golden)
	if !bytes.Equal(got, golden) {
		firstDiff := -1
		for i := 0; i < len(got) && i < len(golden); i++ {
			if got[i] != golden[i] {
				firstDiff = i
				break
			}
		}
		t.Fatalf("bd-data.iso differs from golden outside timestamp fields (first diff at byte %d of %d; sector %d)",
			firstDiff, len(golden), firstDiff/2048)
	}

	gotSidecar, err := os.ReadFile(output + ".json")
	if err != nil {
		t.Fatal(err)
	}
	goldenSidecar, err := os.ReadFile(filepath.Join(dir, "bd-data.iso.json"))
	if err != nil {
		t.Fatal(err)
	}
	normalized := normalizeSidecar(gotSidecar, [][2]string{{work, dir}})
	if normalized != normalizeGoldenSidecar(goldenSidecar) {
		t.Fatalf("bd-data.iso.json mismatch:\n--- got ---\n%s\n--- want ---\n%s", normalized, goldenSidecar)
	}
}
